//! Platform-appropriate directory paths for Bivvy data.
//!
//! Centralizes all platform directory resolution using the `dirs` crate,
//! which follows OS conventions:
//!
//! | Purpose | Linux                         | macOS                              | Windows                        |
//! |---------|-------------------------------|------------------------------------|--------------------------------|
//! | Config  | `$XDG_CONFIG_HOME/bivvy/`     | `~/Library/Application Support/bivvy/` | `{FOLDERID_RoamingAppData}/bivvy/` |
//! | Data    | `$XDG_DATA_HOME/bivvy/`       | `~/Library/Application Support/bivvy/` | `{FOLDERID_RoamingAppData}/bivvy/` |
//! | Cache   | `$XDG_CACHE_HOME/bivvy/`      | `~/Library/Caches/bivvy/`          | `{FOLDERID_LocalAppData}/bivvy/`   |

use std::path::PathBuf;

/// Subdirectory name within platform directories.
const APP_NAME: &str = "bivvy";

/// Returns the platform-appropriate configuration directory for Bivvy.
///
/// Used for user-global configuration files like `config.yml`.
pub fn config_dir() -> Option<PathBuf> {
    dirs::config_dir().map(|d| d.join(APP_NAME))
}

/// Returns the platform-appropriate data directory for Bivvy.
///
/// Used for persistent application data: project state, index,
/// and failure reports.
pub fn data_dir() -> Option<PathBuf> {
    dirs::data_dir().map(|d| d.join(APP_NAME))
}

/// Returns the platform-appropriate cache directory for Bivvy.
///
/// Used for ephemeral data like template caches and update checks.
pub fn cache_dir() -> Option<PathBuf> {
    dirs::cache_dir().map(|d| d.join(APP_NAME))
}

