mod tests {
    use super::*;

    #[test]
    fn config_dir_returns_some() {
        assert!(config_dir().is_some());
    }

    #[test]
    fn config_dir_ends_with_bivvy() {
        let dir = config_dir().unwrap();
        assert!(dir.ends_with("bivvy"));
    }

    #[test]
    fn config_dir_does_not_contain_dot_bivvy() {
        let dir = config_dir().unwrap();
        assert!(!dir.to_string_lossy().contains(".bivvy"));
    }

    #[test]
    fn data_dir_returns_some() {
        assert!(data_dir().is_some());
    }

    #[test]
    fn data_dir_ends_with_bivvy() {
        let dir = data_dir().unwrap();
        assert!(dir.ends_with("bivvy"));
    }

    #[test]
    fn data_dir_does_not_contain_dot_bivvy() {
        let dir = data_dir().unwrap();
        assert!(!dir.to_string_lossy().contains(".bivvy"));
    }

    #[test]
    fn cache_dir_returns_some() {
        assert!(cache_dir().is_some());
    }

